import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class DefaultKeyedValues_removeValue_TriageGen1Test {

    private DefaultKeyedValues keyedValues;

    @Before
    public void setUp() {
        keyedValues = new DefaultKeyedValues();
    }

    @Test
    public void testRemoveValue_KeyNotFound() {
        // Arrange: Add some values
        keyedValues.addValue("A", 1.0);
        keyedValues.addValue("B", 2.0);
        int initialCount = keyedValues.getItemCount();

        // Act: Try to remove a key that doesn't exist
        keyedValues.removeValue("C");

        // Assert: Count should remain unchanged
        assertEquals("Count should not change when key is not found", initialCount, keyedValues.getItemCount());
    }

    @Test
    public void testRemoveValue_KeyExists() {
        // Arrange: Add values
        String key1 = "A";
        String key2 = "B";
        keyedValues.addValue(key1, 1.0);
        keyedValues.addValue(key2, 2.0);
        int initialCount = keyedValues.getItemCount();

        // Act: Remove an existing key
        keyedValues.removeValue(key1);

        // Assert: Count decreased and key is gone
        assertEquals("Count should decrease by 1", initialCount - 1, keyedValues.getItemCount());
        assertEquals("Index of removed key should be -1", -1, keyedValues.getIndex(key1));
        // Verify remaining key is still there
        assertEquals("Remaining key should still exist", 2.0, keyedValues.getValue(key2).doubleValue(), 0.001);
    }

    @Test
    public void testRemoveValue_EmptyCollection() {
        // Arrange: Collection is empty

        // Act: Remove from empty
        keyedValues.removeValue("AnyKey");

        // Assert: No exception and count is 0
        assertEquals(0, keyedValues.getItemCount());
    }

    @Test
    public void testRemoveValue_NullKey() {
        // Arrange
        keyedValues.addValue("A", 1.0);

        // Act: Remove null (assuming getIndex handles null or returns -1)
        keyedValues.removeValue(null);

        // Assert: Count remains same if null is not found
        assertEquals(1, keyedValues.getItemCount());
    }

    @Test
    public void testRemoveValue_SingleElement() {
        // Arrange
        String key = "OnlyOne";
        keyedValues.addValue(key, 10.0);

        // Act
        keyedValues.removeValue(key);

        // Assert
        assertEquals(0, keyedValues.getItemCount());
    }
}
